// CONFIG: nothing required. Input: { "vat": "FR40303265045" } or { "countryCode":"FR","vatNumber":"40303265045" }
const b = $input.first().json.body || $input.first().json;
let cc = (b.countryCode||'').toUpperCase(), num = (b.vatNumber||'');
if (b.vat) { const v = String(b.vat).replace(/[\s.\-]/g,'').toUpperCase(); cc = v.slice(0,2); num = v.slice(2); }
num = String(num).replace(/[\s.\-]/g,'');
const EU = ['AT','BE','BG','CY','CZ','DE','DK','EE','EL','ES','FI','FR','HR','HU','IE','IT','LT','LU','LV','MT','NL','PL','PT','RO','SE','SI','SK','XI'];
if (cc==='GR') cc='EL';
return [{ json: { countryCode: cc, vatNumber: num, formatOk: EU.includes(cc) && /^[0-9A-Z]{2,13}$/.test(num) } }];

const inp = $('Normalize input').first().json;
if (!inp.formatOk) return [{json:{ok:false, status:'INVALID_FORMAT', message:'Not an EU VAT number format (expected e.g. FR40303265045).', input:inp}}];
const r = $input.first().json;
if (r.errorWrappers || r.actionSucceed===false) return [{json:{ok:false,status:'VIES_UNAVAILABLE',message:'VIES temporarily unavailable, retry later. Do NOT treat as invalid.',details:r.errorWrappers||r}}];
const clean = s => (s && s!=='---') ? s.replace(/\n/g,', ') : null;
return [{json:{ ok:true, status: r.valid?'VALID':'NOT_VALID', vat: inp.countryCode+inp.vatNumber, name: clean(r.name), address: clean(r.address), checkedAt: r.requestDate,
 reverseChargeHint: r.valid ? 'B2B EU client with valid VAT: reverse charge may apply (mention "Autoliquidation / Reverse charge, art. 196 Directive 2006/112/EC"). Check with your accountant.' : 'VAT not valid: do not apply reverse charge.',
 invoiceBlock: r.valid ? `${clean(r.name)}\n${clean(r.address)}\nVAT: ${inp.countryCode}${inp.vatNumber}` : null }}];
